VALUES (
  'cef92a41-e284-5fb6-8cfa-783119651eec', '5655c4a7-bc0f-5ffe-aee2-53e2f9789469',
  'Implement the `Iterator` class in class `SLinkedList`.

**Note:** Iterator is a concept of repetitive elements on sequence structures. Iterator is implemented in class `vector`, `list` in STL container in C++ (https://www.geeksforgeeks.org/iterators-c-stl/). Your task is to implement the simple same class with iterator in C++ STL container.

**Please read example and testcase carefully.**

```cpp
template <class T>
class SLinkedList
{
public:
    class Iterator; //forward declaration
    class Node;     //forward declaration
protected:
    Node *head;
    Node *tail;
    int count;
public:
    SLinkedList() : head(NULL), tail(NULL), count(0){};
    ~SLinkedList();
    void add(const T &e);
    void add(int index, const T &e);
    T removeAt(int index);
    bool removeItem(const T &removeItem);
    bool empty();
    int size();
    void clear();
    T get(int index);
    void set(int index, const T &e);
    int indexOf(const T &item);
    bool contains(const T &item);
    string toString();
    SLinkedList(const SLinkedList &list)
    {
        this->count = 0;
        this->head = NULL;
        this->tail = NULL;
    }
    Iterator begin()
    {
        return Iterator(this, true);
    }
    Iterator end()
    {
        return Iterator(this, false);
    }
public:
    class Node
    {
    private:
        T data;
        Node *next;
        friend class SLinkedList<T>;
    public:
        Node()
        {
            next = 0;
        }
        Node(Node *next)
        {
            this->next = next;
        }
        Node(T data, Node *next = NULL)
        {
            this->data = data;
            this->next = next;
        }
    };
    class Iterator
    {
    private:
        SLinkedList<T> *pList;
        Node *current;
        int index; // corresponding with current node
    public:
        Iterator(SLinkedList<T> *pList, bool begin);
        Iterator &operator=(const Iterator &iterator);
        void set(const T &e);
        T &operator*();
        bool operator!=(const Iterator &iterator);

        // Prefix ++ overload
        Iterator &operator++();

        // Postfix ++ overload
        Iterator operator++(int);
    };
};
```

**For example:**

| Test | Result |
| :--- | :--- |
| `SLinkedList<int> list;`<br><br>`int size = 10;`<br>`for(int idx=0; idx < size; idx++){`<br>`    list.add(idx);`<br>`}`<br><br>`SLinkedList<int>::Iterator it;`<br>`int expvalue = 0;`<br>`for(it = list.begin(); it != list.end(); it++){`<br>`    assert(*it == expvalue);`<br>`    expvalue += 1;`<br>`}` | |
| `SLinkedList<int> list;`<br><br>`int size = 10;`<br>`for(int idx=0; idx < size; idx++){`<br>`    list.add(idx);`<br>`}`<br><br>`SLinkedList<int>::Iterator it;`<br>`int expvalue = 0;`<br>`for(it = list.begin(); it != list.end(); ++it){`<br>`    assert(*it == expvalue);`<br>`    expvalue += 1;`<br>`}` | |

**Answer:** (penalty regime: 0, 0, 0, 5, 10 %)

```cpp
template <class T>
SLinkedList<T>::Iterator::Iterator(SLinkedList<T>* pList, bool begin)
{
  /*
   Constructor of iterator
   * Set pList to pList
   * begin = true:
   * * Set current (index = 0) to pList''s head if pList is not NULL
   * * Otherwise set to NULL (index = -1)
   * begin = false:
   * * Always set current to NULL
   * * Set index to pList''s size if pList is not NULL, otherwise 0
  */
}

template <class T>
typename SLinkedList<T>::Iterator& SLinkedList<T>::Iterator::operator=(const Iterator& iterator)
{
  /*
   Assignment operator
   * Set this current, index, pList to iterator corresponding element
  */
}

template <class T>
void SLinkedList<T>::Iterator::remove()
{
  /*
   Remove a node which is pointed by current
   * After remove current points to the previous node of this position
   * If remove at front, current points to previous "node" of head
   * Exception: throw std::out_of_range("Segmentation fault!") if remove is invalid
  */
}

template <class T>
void SLinkedList<T>::Iterator::set(const T& e)
{
  /*
   Set the new value for current node
   * Exception: throw std::out_of_range("Segmentation fault!") if current is invalid
  */
}

template <class T>
T& SLinkedList<T>::Iterator::operator*()
{
  /*
   Get data stored in current node
   * Exception: throw std::out_of_range("Segmentation fault!") if current is invalid
  */
}

template <class T>
bool SLinkedList<T>::Iterator::operator!=(const Iterator& iterator)
{
  /*
   Operator not equals
   * Returns false if two iterators point to the same node and index
  */
}

// Prefix ++ overload
template <class T>
typename SLinkedList<T>::Iterator& SLinkedList<T>::Iterator::operator++()
{
}
```', 9
