INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'efd01e0f-0c06-5420-89e4-ab6fe14ed117', '5655c4a7-bc0f-5ffe-aee2-53e2f9789469',
  'Class `LinkedList` is used to represent single linked list, described as the following:

```cpp
class LinkedList {
public:
    class Node;
private:
    Node* head;
    Node* tail;
    int size;
public:
    class Node {
    private:
        int value;
        Node* next;
        friend class LinkedList;
    public:
        Node() {
            this->next = NULL;
        }
        Node(Node* node) {
            this->value = node->value;
            this->next = node->next;
        }
        Node(int value, Node* next = NULL) {
            this->value = value;
            this->next = next;
        }
    };
    LinkedList(): head(NULL), tail(NULL), size(0) {};
    void partition(int k);
};
```

In this class, `head`, `tail` and `size` are the pointers of the first element, the last element and size of linked list.

Request: Implement function

```cpp
void LinkedList::partition(int k);
```

Rearrange the elements in this linked list by splitting all elements into 3 groups:

- Group I: the value of each element is smaller than `k`.
- Group II: the value of each element is equal to `k`.
- Group III: the value of each element is larger than `k`.

After that, move group I to the head of the linked list, group II after group I, and group III after group II. The orders of the elements in each group must remain unchanged.

Example:

- Given linked list: `10->55->45->42->50`
- `k = 45`

Group I includes elements with values 10 and 42, group II includes 45, and group III includes 55 and 50. The rearranged linked list becomes `10->42->45->55->50`; the order of the elements in each group is unchanged.

Note: Libraries `iostream`, `sstream`, and `using namespace std;` have been used. Other functions may be added, but no other libraries may be added.

Test:

```cpp
LinkedList* l1 = new LinkedList();
l1->add(20); l1->add(30); l1->add(10); l1->add(60); l1->add(40); l1->add(45); l1->add(55);
l1->partition(45);
cout << l1->toString() << "\n";
```

Expected result: `[20, 30, 10, 40, 45, 60, 55]`

Đáp án: ```cpp
void LinkedList::partition(int k) {
    Node* h = head; //
    int size = this->size;
    int* arr = new int[size];
    int move = 0;
    for (h = head; h != NULL; h = h->next)
    {
        if (h->value < k) {arr[move] = h->value ; ++move;}
    }
    for (h = head; h != NULL; h = h->next)
    {
        if (h->value == k) {arr[move] = h->value ; ++move;}
    }
    for (h = head; h != NULL; h = h->next)
    {
        if (h->value > k) {arr[move] = h->value ; ++move;}
    }
    int i = 0;
    for (h = head; h != NULL; h = h->next)
    {
        h->value = arr[i];
        ++i;
    }
    tail->value = arr[size-1];
    delete[] arr;
    return;
}
```', 10
);

